'use strict';
let DATA,view='overview',page=1,reviewPage=1,reviewKind='all',sort='order',affGroup='product';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>n.toLocaleString('ko-KR')+'원',pct=n=>(n*100).toFixed(1)+'%',mean=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:null,fmt=n=>n==null?'—':n.toLocaleString('ko-KR');
const TABS=[['overview','01','분석 개요'],['products','02','상품 탐색'],['feedback','03','고객 피드백'],['affinity','04','애착 신호'],['method','05','데이터·지표 설명']];
const TITLES={overview:['상품과 고객경험 한눈에','판매 구성을 파악하고, 고객 피드백에서 개선 기회를 발견하세요.'],products:['취향을 만드는 상품 구성','카테고리·브랜드·가격을 비교하고 개별 상품의 고객 의견을 확인하세요.'],feedback:['별점 너머, 고객의 목소리','구매 이유와 개선 요구를 분리해서 읽습니다. 모든 텍스트는 분석자가 작성한 요약입니다.'],affinity:['다시 찾는 이유를 읽다','재구매와 선호 표현을 상품·브랜드 수준에서 탐색합니다. 개인별 고객 순위가 아닙니다.'],method:['데이터를 이해하는 기준','측정 범위와 계산법을 확인하고, 해석 가능한 지표를 사용하세요.']};
// Reviewed evidence annotations, version 1.0. Each label refers to a collected summary, not an identified person.
const SIGNALS={ 'demo-1:R001':{kind:'재구매 경험',reason:'합성 예제: 가상 재구매 표현'}, 'demo-2:R001':{kind:'구매 의향',reason:'합성 예제: 가상 추가 구매 의향'} };
const ISSUES={'demo-1':['R002'],'demo-3':['R002']};
const key=r=>r.product+':'+r.id,signal=r=>r.type==='리뷰'?SIGNALS[key(r)]:null,issue=r=>r.type==='리뷰'&&(ISSUES[r.product]||[]).includes(r.id);
function init(){ $('#tabs').innerHTML=TABS.map(([id,no,label])=>`<button data-view="${id}"><span>${no}</span>${label}</button>`).join('');$('#category').innerHTML+=[...new Set(DATA.products.map(p=>p.category))].map(c=>`<option>${esc(c)}</option>`).join('');$('#brand').innerHTML+=[...new Set(DATA.products.map(p=>p.brand))].sort().map(c=>`<option>${esc(c)}</option>`).join('');$('#tabs').onclick=e=>{let b=e.target.closest('[data-view]');if(b){view=b.dataset.view;page=reviewPage=1;render()}};['category','brand','search'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',()=>{page=reviewPage=1;render()}));$('#reset').onclick=()=>{$('#category').value=$('#brand').value=$('#search').value='';page=reviewPage=1;render()};$('#methodTop').onclick=()=>{view='method';render()};$('#closeDetail').onclick=()=>$('#detail').close();$('#export').onclick=exportCurrent;$('#content').addEventListener('click',e=>{let b=e.target.closest('[data-product]');if(b)detail(b.dataset.product);let c=e.target.closest('[data-category]');if(c){$('#category').value=c.dataset.category;page=reviewPage=1;render()}let v=e.target.closest('[data-view]');if(v){view=v.dataset.view;render()}let pn=e.target.closest('[data-page]');if(pn){page=+pn.dataset.page;render()}let rn=e.target.closest('[data-rpage]');if(rn){reviewPage=+rn.dataset.rpage;render()}});$('#content').addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;page=1;render()}if(e.target.id==='reviewKind'){reviewKind=e.target.value;reviewPage=1;render()}if(e.target.id==='affGroup'){affGroup=e.target.value;render()}});render()}
function selection(){let q=$('#search').value.trim().toLowerCase(),cat=$('#category').value,brand=$('#brand').value;return DATA.products.filter(p=>(!cat||p.category===cat)&&(!brand||p.brand===brand)&&(!q||(p.name+' '+p.brand+' '+p.copy+' '+DATA.feedback.filter(r=>r.product===p.id).map(r=>r.text).join(' ')).toLowerCase().includes(q)))}
const feedback=ps=>{let ids=new Set(ps.map(p=>p.id));return DATA.feedback.filter(r=>ids.has(r.product))};const reviews=rs=>rs.filter(r=>r.type==='리뷰');const byId=id=>DATA.products.find(p=>p.id===id);function stats(rs){let r=reviews(rs),s=r.filter(signal);return {n:r.length,mean:mean(r.map(x=>x.rating)),s:s.length,rate:r.length?s.length/r.length:null,issues:r.filter(issue),repeat:s.filter(x=>signal(x).kind==='재구매 경험').length,intent:s.filter(x=>signal(x).kind==='구매 의향').length,brand:s.filter(x=>signal(x).kind==='브랜드 선호').length}}
function metric(label,val,desc,hi=false){return `<div class="metric ${hi?'highlight':''}"><div class="label">${label}</div><strong>${val}</strong><div class="desc">${desc}</div></div>`}function bars(items,orange=false,click=false){let max=Math.max(1,...items.map(x=>x[1]));return `<div class="barchart">${items.map(([label,n])=>`<div class="barrow">${click?`<button data-category="${esc(label)}">${esc(label)}</button>`:`<span>${esc(label)}</span>`}<div class="track"><div class="fill ${orange?'orange':''}" style="width:${n/max*100}%"></div></div><b>${n}</b></div>`).join('')}</div>`}function countBy(a,fn){let m={};a.forEach(x=>{let k=fn(x);m[k]=(m[k]||0)+1});return Object.entries(m).sort((a,b)=>b[1]-a[1])}
function render(){let ps=selection(),rs=feedback(ps),s=stats(rs);$('#tabs').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#pageTitle').textContent=TITLES[view][0];$('#pageSub').textContent=TITLES[view][1];$('#scope').textContent=`${esc(DATA.products[0]?.platform||"데이터")} · ${ps.length} / ${DATA.products.length}개 상품 카드 · 피드백 보유 ${ps.filter(p=>rs.some(r=>r.product===p.id)).length}개 상품 · 분석 리뷰 ${s.n}건 / 문의 ${rs.filter(r=>r.type!=='리뷰').length}건 · ${esc(DATA.date)}`;$('#content').innerHTML=view==='overview'?overview(ps,rs):view==='products'?productView(ps):view==='feedback'?feedbackView(ps,rs):view==='affinity'?affinity(ps,rs):method();$('#export').textContent=view==='products'?'상품 결과 내보내기 ↓':view==='affinity'?'애착 지표 내보내기 ↓':view==='overview'?'분석 요약 내보내기 ↓':view==='method'?'원본 데이터 보기 ↓':'피드백 내보내기 ↓'}
function overview(ps,rs){let s=stats(rs),prices=ps.map(p=>p.price).sort((a,b)=>a-b),median=prices.length?(prices[Math.floor((prices.length-1)/2)]+prices[Math.ceil((prices.length-1)/2)])/2:null;return `<div class="metrics">${metric('분석 상품 카드',ps.length,'색상·옵션별 별도 노출 포함')}${metric('표시가격 중앙값',median==null?'—':money(median),'메인 카드 가격 / 배송·옵션 별도')}${metric('수집 리뷰 평균',s.mean?.toFixed(2)||'—',`${s.n}건 기준 / 상품별 표본 상이`)}${metric('애착 표현율',s.rate===null?'—':pct(s.rate),`${s.s} / ${s.n}개 리뷰 · 상품·브랜드 신호`,true)}</div><div class="grid2"><section class="card"><h2>상품 구성</h2><p class="sub">카테고리별 노출 카드 수 · 막대 이름을 누르면 필터링</p>${bars(countBy(ps,p=>p.category),false,true)}</section><section class="card"><h2>가격대 분포</h2><p class="sub">결제금액이 아닌 메인 카드 표시가격</p>${bars([['3만원 이하',ps.filter(p=>p.price<=30000).length],['3만~5만원',ps.filter(p=>p.price>30000&&p.price<=50000).length],['5만~10만원',ps.filter(p=>p.price>50000&&p.price<=100000).length],['10만~20만원',ps.filter(p=>p.price>100000&&p.price<=200000).length],['20만원 초과',ps.filter(p=>p.price>200000).length]],true)}</section></div><div class="grid2"><section class="card"><h2>높은 별점에도 남은 개선 의견</h2><p class="sub">분석자가 요약 내용을 검토한 개선 의견 포함 리뷰</p><div class="signal"><div><strong>${s.issues.length}</strong>개선 의견</div><div><strong>${s.issues.filter(r=>r.rating===5).length}</strong>그중 5점 리뷰</div><div><strong>${rs.filter(r=>r.public==='비밀글').length}</strong>비밀 문의</div></div><p class="small muted">낮은 별점만 보면 포장·배송·크기 등 개선 신호를 놓칠 수 있습니다. 개선 의견은 결함 확정 건수가 아닙니다.</p><button class="plain" data-view="feedback">고객 의견 살펴보기 ↗</button></section><section class="card"><h2>분석 범위</h2><p class="sub">수집량과 전체 리뷰 수를 구분합니다.</p>${coverageTable(ps)}<p class="mini">현재 화면은 합성 예제입니다. 상품별 실제 분석은 승인된 데이터를 별도로 연결하세요.</p></section></div><div class="callout"><strong>리서치 포인트</strong> · 고객이 갖고 싶어지는 이유와 구매를 망설이는 이유를 함께 보세요. 애착 표현의 대상은 상품·브랜드이며, 29CM 플랫폼 자체 애착은 현재 데이터로 측정할 수 없습니다.</div>`}
function coverageTable(ps){let a=ps.filter(p=>DATA.feedback.some(r=>r.product===p.id));return a.length?`<table><thead><tr><th>상품</th><th>수집 / 전체</th><th>범위</th></tr></thead><tbody>${a.map(p=>{let r=DATA.feedback.filter(x=>x.product===p.id&&x.type==='리뷰');return `<tr><td><button class="productbtn" data-product="${p.id}">${esc(p.brand)}</button></td><td>${r.length} / ${r[0].total}</td><td><span class="badge ${r.length===r[0].total?'':'warn'}">${r.length===r[0].total?'전체':'추천순 표본'}</span></td></tr>`}).join('')}</tbody></table>`:'<div class="empty">피드백 미수집 상품만 선택되었습니다.</div>'}
function ordered(ps){return [...ps].sort((a,b)=>sort==='priceAsc'?a.price-b.price:sort==='priceDesc'?b.price-a.price:sort==='affinity'?(stats(feedback([b])).rate??-1)-(stats(feedback([a])).rate??-1):0)}
function productView(ps){let all=ordered(ps),slice=all.slice((page-1)*12,page*12);return `<section class="card"><div class="tabletop"><div><h2>상품 목록 <span class="muted">${ps.length}</span></h2><p class="sub">상품명을 눌러 고객 의견과 애착 신호의 근거를 확인하세요.</p></div><select id="sort" aria-label="상품 정렬">${[['order','노출순'],['priceAsc','낮은 가격순'],['priceDesc','높은 가격순'],['affinity','애착 표현율순']].map(([v,t])=>`<option value="${v}" ${sort===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="tablewrap"><table><thead><tr><th>브랜드 / 상품명</th><th>카테고리</th><th>표시가격</th><th>할인율</th><th>관심 표시</th><th>수집 리뷰</th><th>애착 표현율</th></tr></thead><tbody>${slice.map(p=>{let s=stats(feedback([p]));return `<tr><td><button class="productbtn" data-product="${p.id}"><b>${esc(p.brand)}</b><span>${esc(p.name)}</span></button></td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td>${p.discount==null?'미표시':p.discount+'%'}</td><td>${esc(p.likes)}</td><td>${s.n||'미수집'}</td><td>${s.rate==null?'<span class="muted">측정 불가</span>':`<span class="affnum">${pct(s.rate)}</span><div class="mini">${s.s}/${s.n}건</div>`}</td></tr>`}).join('')}</tbody></table></div>${!ps.length?'<div class="empty">일치하는 상품이 없습니다.</div>':''}${pager(page,Math.ceil(ps.length/12),'page')}</section><div class="scope">관심 수는 축약 표시 그대로입니다. 판매량·구매전환율이 아닙니다. 미수집 상품의 애착 표현율은 0%로 처리하지 않습니다.</div>`}
function pager(p,total,name){return `<div class="pagination"><button data-${name}="${p-1}" ${p<=1?'disabled':''}>이전</button><span>${total? p:0} / ${total}</span><button data-${name}="${p+1}" ${p>=total?'disabled':''}>다음</button></div>`}
function visibleReviews(rs){return rs.filter(r=>reviewKind==='all'||reviewKind==='issue'&&issue(r)||reviewKind==='fiveIssue'&&issue(r)&&r.rating===5||reviewKind==='aff'&&signal(r)||reviewKind==='qna'&&r.type!=='리뷰'||reviewKind==='low'&&r.type==='리뷰'&&r.rating<=3)}
function reviewCard(r){let p=byId(r.product),sig=signal(r);return `<article class="review"><div class="reviewtop"><span><strong>${esc(p.brand)}</strong> · ${esc(r.id)} <span class="mini">리뷰 단위 익명번호</span></span><span>${r.rating?`<span class="stars">${'★'.repeat(r.rating)} ${r.rating}점</span>`:`<span class="badge">${esc(r.qtype)} · ${esc(r.public)}</span>`} · ${r.date}</span></div><p>${esc(r.text)}</p>${sig?`<p class="mini">신호 근거: ${esc(sig.reason)}</p>`:""}<div class="tags">${sig?`<span class="badge">애착 신호 · ${sig.kind}</span>`:''}${issue(r)?'<span class="badge warn">개선 의견 포함</span>':''}${r.tags.map(t=>`<span class="badge">${esc(t)}</span>`).join('')}</div><div class="mini" style="margin-top:10px">${esc(r.scope)}${r.fit?' · 사이즈 선택: '+esc(r.fit):''} · <a href="${esc(r.url)}" target="_blank" rel="noopener">예제 참고 링크 ↗</a></div></article>`}
function feedbackView(ps,rs){let s=stats(rs),v=visibleReviews(rs),ratings=[5,4,3,2,1].map(n=>[n+'점',reviews(rs).filter(r=>r.rating===n).length]);return `<div class="grid2"><section class="card"><h2>수집 리뷰의 별점 분포</h2><p class="sub">${s.n}건 기준 · 문의 제외 · 추천순 표본 포함</p>${bars(ratings)}</section><section class="card"><h2>자주 언급된 주제</h2><p class="sub">리뷰의 분석 태그 빈도 · 복수 태그 / 긍·부정 통합</p>${bars(countBy(reviews(rs).flatMap(r=>r.tags),x=>x).slice(0,5),true)}</section></div><section class="card"><div class="tabletop"><div><h2>고객 의견 ${v.length}건</h2><p class="sub">요약 텍스트와 분석 태그. 비밀 문의의 본문은 수집하지 않았습니다.</p></div><div class="controls"><select id="reviewKind" aria-label="피드백 유형">${[['all','전체 리뷰·문의'],['issue','개선 의견'],['fiveIssue','5점 속 개선 의견'],['aff','애착 신호'],['low','3점 이하'],['qna','상품 문의']].map(([k,t])=>`<option value="${k}" ${reviewKind===k?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="reviewlist">${v.slice((reviewPage-1)*10,reviewPage*10).map(reviewCard).join('')||'<div class="empty">선택한 조건에 해당하는 피드백이 없습니다.</div>'}</div>${pager(reviewPage,Math.ceil(v.length/10),'rpage')}</section>`}
function affinity(ps,rs){let s=stats(rs);let groups=affGroup==='product'?ps.filter(p=>reviews(feedback([p])).length).map(p=>({label:p.brand,name:p.name,ps:[p]})):countBy(ps,p=>p.category).map(([c])=>({label:c,name:'카테고리 내 수집 리뷰 기준',ps:ps.filter(p=>p.category===c)}));groups=groups.map(g=>({...g,s:stats(feedback(g.ps))})).sort((a,b)=>(b.s.rate??-1)-(a.s.rate??-1));return `<div class="notice"><strong>플랫폼 충성도는 측정 불가</strong> · 고객 식별자와 플랫폼 이용·주문 이력이 없습니다. 아래 지표는 상품·브랜드를 다시 찾는 표현의 비율입니다. 리뷰 작성자를 개인 고객으로 매칭하거나 타인보다 높은 플랫폼 애착을 판정하지 않습니다.</div><div class="metrics">${metric('애착 표현율',s.rate==null?'—':pct(s.rate),`${s.s} / ${s.n}개 리뷰`,true)}${metric('재구매 경험',s.repeat,'기존 사용 후 재구매·추가 구매 명시')}${metric('구매 의향',s.intent,'향후 본인용·다른 상품 구매 의향')}${metric('브랜드 선호',s.brand,'브랜드 선호를 명시한 리뷰')}</div><section class="card"><div class="tabletop"><div><h2>애착 표현 비교</h2><p class="sub">표현이 없다는 것은 애착이 없다는 뜻이 아닙니다. 비율은 모집단 추정치가 아닙니다.</p></div><select id="affGroup" aria-label="애착 집계 기준"><option value="product" ${affGroup==='product'?'selected':''}>상품별</option><option value="category" ${affGroup==='category'?'selected':''}>카테고리별</option></select></div><div class="tablewrap"><table><thead><tr><th>대상</th><th>애착 표현율</th><th>신호 / 수집</th><th>피드백 보유 상품</th><th>수집범위</th></tr></thead><tbody>${groups.map(g=>`<tr><td>${affGroup==='product'?`<button class="productbtn" data-product="${g.ps[0].id}"><b>${esc(g.label)}</b><span>${esc(g.name)}</span></button>`:esc(g.label)}</td><td><span class="affnum">${g.s.rate==null?'측정 불가':pct(g.s.rate)}</span></td><td>${g.s.s} / ${g.s.n}</td><td>${g.ps.filter(p=>reviews(feedback([p])).length).length} / ${g.ps.length}</td><td>${g.s.n?([...new Set(feedback(g.ps).filter(r=>r.type==='리뷰').map(r=>r.scope.includes('표본')?'추천순 표본':'전체'))].join(' + ')):'미수집'}</td></tr>`).join('')}</tbody></table></div></section><div class="callout"><strong>계산식</strong> · 신호가 하나 이상 있는 리뷰 수 ÷ 수집 리뷰 수 × 100. 한 리뷰는 한 번만 계산합니다. Q&A·찜 수·별점은 분자와 분모에 넣지 않습니다.</div><section class="card"><h2>애착 신호의 근거</h2><p class="sub">표현을 발견한 리뷰 단위의 후보입니다. 동일 고객의 반복 행동 여부는 검증하지 않았습니다.</p><div class="reviewlist">${reviews(rs).filter(signal).map(reviewCard).join('')||'<div class="empty">선택 범위에서 명시적 애착 표현이 확인되지 않았습니다.</div>'}</div></section>`}
function method(){return `<section class="card definition"><h2>공개 저장소 실행 예제</h2><div class="notice">현재 데이터는 모두 기능 검증용 합성 예제입니다. 실제 고객 리뷰·문의 또는 실제 분석 결과를 포함하지 않습니다. 상단 README 이미지는 최초 Sites 앱의 실제 스냅샷 화면입니다.</div><p>상품 ${DATA.products.length}개 · 리뷰 ${reviews(DATA.feedback).length}건 · 문의 ${DATA.feedback.filter(r=>r.type!=='리뷰').length}건</p><h3>애착 표현율</h3><div class="formula">신호 포함 리뷰 ÷ 수집 리뷰 × 100</div><p>SIGNALS의 검토 주석을 근거로 재구매 경험·구매 의향·브랜드 선호를 집계합니다. 분모에서 Q&A는 제외합니다. 카테고리는 리뷰 분자·분모를 각각 합산합니다.</p><p>개인별 플랫폼 충성도가 아닙니다. 고객 식별자와 주문·이용 이력이 없으므로 같은 순번의 리뷰를 동일인으로 연결하지 않습니다.</p><h3>데이터 연결</h3><p>prepare_data.py의 --products, --feedback으로 이 저장소의 정규화 CSV 형식에 맞는 로컬 입력을 지정할 수 있습니다. 실제 데이터를 공개 저장소에 넣으려면 별도 공개 권한을 먼저 확인하세요.</p><div class="links"><a href="example_products.csv" download>합성 상품 CSV ↓</a><a href="example_feedback.csv" download>합성 피드백 CSV ↓</a></div></section>`}
function detail(id){let p=byId(id),rs=feedback([p]),s=stats(rs);$('#detailBody').innerHTML=`<p class="sectionlabel">합성 예제 / ${esc(p.category)} / ${esc(p.brand)}</p><h2 class="detailtitle">${esc(p.name)}</h2><div class="metrics">${metric('표시가격',money(p.price),'옵션·배송 조건 별도')}${metric('관심 표시',esc(p.likes),'축약 표시 / 판매량 아님')}${metric('수집 평균',s.mean?.toFixed(2)||'—',s.n+'개 리뷰')}${metric('애착 표현율',s.rate==null?'측정 불가':pct(s.rate),s.s+'/'+s.n+'건',true)}</div><p class="small">배송: ${esc(p.shipping)} · 옵션비 별도: ${esc(p.options)}</p><p class="small muted">큐레이션 문구: ${esc(p.copy)}</p><div class="links" style="margin:15px 0"><a href="${esc(p.url)}" target="_blank" rel="noopener">${p.id.startsWith('card-')?'출처 메인 페이지':'예제 참고 링크'} ↗</a></div>${s.n?`<div class="callout">${esc(reviews(rs)[0].scope)} / 전체 표시 리뷰 ${reviews(rs)[0].total}건. 리뷰 내용은 수집 당시 분석 요약입니다.</div><div class="reviewlist">${rs.map(reviewCard).join('')}</div>`:'<div class="empty">이 상품의 리뷰·문의는 아직 수집하지 않았습니다.<br>상품 정보만 확인할 수 있습니다.</div>'}`;$('#detail').showModal()}
function exportCsv(name,rows){if(!rows.length){alert('내보낼 결과가 없습니다.');return}let keys=Object.keys(rows[0]),cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"',text='\ufeff'+[keys,...rows.map(r=>keys.map(k=>r[k]))].map(r=>r.map(cell).join(',')).join('\r\n');let u=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();URL.revokeObjectURL(u)}
function exportCurrent(){let ps=selection(),rs=feedback(ps);if(view==='method'){let a=document.createElement('a');a.href='example_feedback.csv';a.download='example_feedback.csv';a.click();return}if(view==='products')exportCsv('29CM_filtered_products.csv',ps.map(p=>({브랜드:p.brand,상품명:p.name,카테고리:p.category,표시가격:p.price,관심축약표시:p.likes,수집리뷰수:stats(feedback([p])).n,애착표현율:stats(feedback([p])).rate==null?'미수집':pct(stats(feedback([p])).rate),출처:p.url})));else if(view==='feedback')exportCsv('29CM_filtered_feedback.csv',visibleReviews(rs).map(r=>({상품ID:r.product,리뷰순번:r.id,유형:r.type,작성일:r.date,별점:r.rating,요약:r.text,애착신호:signal(r)?.kind||'',개선의견:issue(r)?'있음':'미표시',출처:r.url})));else if(view==='affinity'){let groups=affGroup==='product'?ps.map(p=>({label:p.name,p:[p]})):[...new Set(ps.map(p=>p.category))].map(c=>({label:c,p:ps.filter(p=>p.category===c)}));exportCsv('29CM_affinity_expressions.csv',groups.map(g=>{let s=stats(feedback(g.p));return {집계대상:g.label,수집리뷰수:s.n,신호리뷰수:s.s,애착표현율:s.rate==null?'측정불가':pct(s.rate),재구매:s.repeat,구매의향:s.intent,브랜드선호:s.brand,지표대상:'상품·브랜드 표현; 플랫폼 충성도 아님'}}))}else{let s=stats(rs);exportCsv('29CM_analysis_summary.csv',[{상품수:ps.length,수집리뷰수:s.n,평균별점:s.mean,개선의견수:s.issues.length,애착신호수:s.s,애착표현율:s.rate==null?'측정불가':pct(s.rate),조회일:DATA.date}])}}
fetch('data.json').then(r=>{if(!r.ok)throw Error('데이터 로드 실패');return r.json()}).then(d=>{DATA=d;init()}).catch(e=>{$('#content').innerHTML='<div class="notice">데이터를 불러오지 못했습니다. 페이지를 새로고침해 주세요.</div>';console.error(e)});
